def is_header_row(row):
    # Header rows contain column category labels (not year/month labels)
    return row[0] in ('', 'End of fiscal year or month') or row[0].endswith(')') or not any(c.isdigit() for c in row[0])

def clean_value(val):
    # Remove footnote markers, stars, letters
    val = val.strip()
    # Remove footnote markers like 1/, 2/, r/, p/, e/, *, etc.
    val = val.lstrip('*/rp0123456789/ \u2020\u2021')
    # Handle negative in parentheses: (123) -> -123
    if val.startswith('(') and val.endswith(')'):
        val = '-' + val[1:-1]
    # Remove commas
    val = val.replace(',', '')
    # Remove any remaining non-digit/- chars except .
    val = re.sub(r'[^\d.\-]', '', val)
    return val

import re

def has_leading_one(val_str):
    cleaned = clean_value(val_str)
    if not cleaned:
        return False
    try:
        # Get the first significant digit
        for c in cleaned:
            if c.isdigit():
                return c == '1'
        return False
    except:
        return False

